  ('25dd1ef1-ca5b-58cc-9458-f17f43ed8621', 'Fora do formato: Terços e adorações antes da missa em alguns dias', '{"http://www.diocesederiobranco.org.br/paroquias/paroquia-santa-rosa-de-lima--santa-rosa-do-purus","http://www.diocesederiobranco.org.br/paroquias/paroquia-santa-rosa-de-lima--santa-rosa-do-purus"}', 'media'),
  ('3307dbcd-3058-5b48-bc91-7eadd9784fbc', 'Ponto no mapa aproximado: centro da cidade.', '{"http://www.diocesederiobranco.org.br/paroquias/paroquia-nossa-senhora-das-dores--brasileia","http://www.diocesederiobranco.org.br/paroquias/paroquia-nossa-senhora-das-dores--brasileia"}', 'media'),
  ('4d6d1933-61ae-5079-b297-54b985023e97', 'Criada em 2001. Sem horários publicados na página da diocese. Ponto no mapa aproximado: centro da cidade.', '{"http://www.diocesederiobranco.org.br/paroquias/paroquia-sao-sebastiao-2001-"}', ''),
  ('ccaf0072-13a8-575a-a81c-233cb5ac2e55', 'Criada em 1910. Fora do formato: Missa das famílias, adoração e primeira sexta sem horário na página Ponto no mapa aproximado: centro da cidade.', '{"http://www.diocesederiobranco.org.br/paroquias/paroquia-sao-sebastiao--xapuri--1910","http://www.diocesederiobranco.org.br/paroquias/paroquia-sao-sebastiao--xapuri--1910"}', 'media'),
