  ('e7ad3106-dc8c-5964-8333-8d4c73a40d54', 'Em Boca do Acre (AM); pertence à Diocese de Rio Branco.', '{"http://www.diocesederiobranco.org.br/paroquias/paroquia-sao-pedro--boca-do-acre","http://www.diocesederiobranco.org.br/paroquias/paroquia-sao-pedro--boca-do-acre"}', 'media'),
  ('fd140f2a-53de-5516-a8ea-1eb30e704b78', 'Em Boca do Acre (AM); pertence à Diocese de Rio Branco. Sem horários publicados. Ponto no mapa aproximado: centro da cidade.', '{"http://www.diocesederiobranco.org.br/paroquias/paroquia-sao-francisco-de-assis--boca-do-acre"}', ''),
  ('4c814fc9-ded4-5335-a7c9-6fe22c8a4446', 'Sede da Paróquia Nossa Senhora da Glória. Endereço e telefone vêm do diretório GCatholic. Fora do formato: Quinta: adoração e confissões depois da missa das 6h; novena do Perpétuo Socorro na terça às 17h', '{"https://diocesecruzeirodosul.org.br/paroquia/nossa-senhora-da-gloria-cruzeiro-do-sul-ac/","https://gcatholic.org/churches/brazil/2693"}', 'media'),
  ('a6ef1f6b-b2aa-5d47-bb02-34f9ceb8da7b', 'Fundada em 1959; 22 comunidades, metade urbanas e metade rurais. Fora do formato: Confissão com agendamento pelo telefone da paróquia', '{"https://diocesecruzeirodosul.org.br/paroquia/nossa-senhora-aparecida-cruzeiro-do-sul-ac/","https://diocesecruzeirodosul.org.br/paroquia/nossa-senhora-aparecida-cruzeiro-do-sul-ac/"}', 'media'),
  ('f930c607-70bc-50eb-98d5-5548c6bbed56', 'Fundada em 1978; cinco comunidades. Fora do formato: Domingo às 8h: celebração da Palavra', '{"https://diocesecruzeirodosul.org.br/paroquia/nossa-senhora-do-rosario-cruzeiro-do-sul-ac/","https://diocesecruzeirodosul.org.br/paroquia/nossa-senhora-do-rosario-cruzeiro-do-sul-ac/"}', 'media'),
  ('50d07633-a422-5628-bacb-1100db88ae11', 'Fora do formato: Missas de semana às 19h30 nas comunidades, em rodízio (Santa Luzia, São José, Sagrado Coração de Jesus, Santo Expedito) Ponto no mapa aproximado: centro da cidade.', '{"https://diocesecruzeirodosul.org.br/paroquia/sao-francisco-de-assis-mancio-lima-ac/","https://diocesecruzeirodosul.org.br/paroquia/sao-francisco-de-assis-mancio-lima-ac/"}', 'media'),
  ('3e3064d3-74f1-5ee6-bf9f-ffd80e5a36b4', 'Fora do formato: Confissões de terça a sexta e antes das missas; 1º sábado às 7h na capela da casa de missão; Também no último domingo do mês, às 17h Ponto no mapa aproximado: centro da cidade.', '{"https://diocesecruzeirodosul.org.br/paroquia/sao-jose-rodrigues-alves-ac/","https://diocesecruzeirodosul.org.br/horarios-de-missa/"}', 'media'),
  ('e8fd0135-b876-5ae6-a307-b065181ea3cf', '18 comunidades urbanas e rurais. Fora do formato: Domingo às 19h: celebração da Palavra; Domingo às 19h: celebração da Palavra; Domingo às 19h: celebração da Palavra Ponto no mapa aproximado: centro da cidade.', '{"https://diocesecruzeirodosul.org.br/paroquia/nossa-senhora-imaculada-conceicao-de-maria-porto-walter-ac/"}', 'media'),
  ('146c8528-d7e7-5492-92e9-dcbaa2914e55', 'A página geral de horários da diocese traz outros horários, nas comunidades São Sebastião e Santo Antônio.', '{"https://diocesecruzeirodosul.org.br/paroquia/paroquia-sao-sebastiao-marechal-thaumaturgo-ac/","https://diocesecruzeirodosul.org.br/paroquia/paroquia-sao-sebastiao-marechal-thaumaturgo-ac/"}', 'media'),
  ('f3df54d6-06fe-587e-9f04-0ddfbb6bbcea', '', '{"https://diocesecruzeirodosul.org.br/paroquia/sao-jose-tarauaca-ac/","https://diocesecruzeirodosul.org.br/paroquia/sao-jose-tarauaca-ac/"}', 'media'),
  ('45fc0ff5-5a9b-5da4-baf5-c074088cd10b', 'Atendida pelos padres da Paróquia São José de Tarauacá; 11 comunidades urbanas e rurais. Ponto no mapa aproximado: centro da cidade.', '{"https://diocesecruzeirodosul.org.br/paroquia/sao-sebastiao-jordao-ac/"}', 'media'),
